import React, { useState, useEffect } from 'react';
import { createUser, getUsers, deleteUser, updateUser, getFranchises } from '../services/api';

const CreateUser = () => {
  const [formData, setFormData] = useState({
    username: '',
    password: '',
    name: '',
    role: 'user',
    franchiseId: [], // Allow multiple franchises selection
  });

  const [franchises, setFranchises] = useState([]);
  const [users, setUsers] = useState([]);
  const [editingUser, setEditingUser] = useState(null);

  useEffect(() => {
    const fetchFranchises = async () => {
      try {
        const response = await getFranchises();
        setFranchises(response.data);
      } catch (error) {
        alert('Error fetching franchises: ' + (error.response?.data?.message || error.message));
      }
    };

    const fetchUsers = async () => {
      try {
        const response = await getUsers();
        setUsers(response);
      } catch (error) {
        alert('Error fetching users: ' + (error.response?.data?.message || error.message));
      }
    };

    fetchFranchises();
    fetchUsers();
  }, []);

  const handleChange = (e) => {
    const { name, value } = e.target;
    if (name === 'franchiseId') {
      // Handle multiple franchise selection
      setFormData({ ...formData, [name]: typeof value === 'string' ? value.split(',') : value });
    } else {
      setFormData({ ...formData, [name]: value });
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      if (editingUser) {
        await updateUser(editingUser._id, formData);
        alert('User updated successfully!');
      } else {
        await createUser(formData);
        alert('User created successfully!');
      }

      setEditingUser(null);
      setFormData({
        username: '',
        password: '',
        name: '',
        role: 'user',
        franchiseId: [],
      });

      const response = await getUsers();
      setUsers(response);
    } catch (error) {
      alert('Error creating/updating user: ' + (error.response?.data?.message || error.message));
    }
  };

  const handleEdit = (user) => {
    setEditingUser(user);
    setFormData({
      username: user.username,
      password: '', // Clear password when editing
      name: user.name,
      role: user.role,
      franchiseId: user.franchiseId || [], // Handle multiple franchises for editing
    });
  };

  const handleDelete = async (userId) => {
    try {
      await deleteUser(userId);
      alert('User deleted successfully!');
      const response = await getUsers();
      setUsers(response);
    } catch (error) {
      console.error("Failed to delete user:", error.message);
      alert('Failed to delete user. Please try again.');
    }
  };

  const isEditingSelf = editingUser && editingUser.role === 'superadmin';

  return (
    <div className="create-user-container">
      <h1>{editingUser ? 'Edit User' : 'Create User'}</h1>
      <form onSubmit={handleSubmit} className="form-container">
        <div className="form-group">
          <label htmlFor="username">Username:</label>
          <input
            id="username"
            name="username"
            placeholder="Username"
            value={formData.username}
            onChange={handleChange}
            required
          />
        </div>
        <div className="form-group">
          <label htmlFor="password">Password:</label>
          <input
            id="password"
            name="password"
            type="password"
            placeholder="Password"
            value={formData.password}
            onChange={handleChange}
            required={!editingUser}
          />
        </div>
        <div className="form-group">
          <label htmlFor="name">Name:</label>
          <input
            id="name"
            name="name"
            placeholder="Full Name"
            value={formData.name}
            onChange={handleChange}
            required
          />
        </div>
        <div className="form-group">
          <label htmlFor="role">Role:</label>
          <select
            id="role"
            name="role"
            value={formData.role}
            onChange={handleChange}
            disabled={isEditingSelf} // Disable role editing if editing superadmin
          >
            <option value="user">User</option>
            <option value="admin">Admin</option>
          </select>
        </div>
        <div className="form-group">
          <label htmlFor="franchiseId">Franchise:</label>
          <select
            id="franchiseId"
            name="franchiseId"
            value={formData.franchiseId}
            onChange={handleChange}
            required
            multiple // Allow multiple selections
            disabled={isEditingSelf} // Disable franchise editing if editing superadmin
          >
            <option value="">Select Franchise</option>
            {franchises.map((franchise) => (
              <option key={franchise._id} value={franchise._id}>
                {franchise.name} - {franchise.location}
              </option>
            ))}
          </select>
        </div>
        <button type="submit" className="submit-btn">{editingUser ? 'Update User' : 'Create User'}</button>
      </form>

      <h2>All Users</h2>
      <table className="user-table">
        <thead>
          <tr>
            <th>Username</th>
            <th>Name</th>
            <th>Role</th>
            <th>Franchise</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {users.map((user) => {
            const franchiseNames = user.franchiseId?.map((franchiseId) => {
              const franchise = franchises.find(f => f._id === franchiseId);
              return franchise ? franchise.name : 'N/A';
            }).join(', ') || 'No franchise assigned';

            return (
              <tr key={user._id}>
                <td>{user.username}</td>
                <td>{user.name}</td>
                <td>{user.role}</td>
                <td>{franchiseNames}</td>
                <td>
                  <button onClick={() => handleEdit(user)} className="edit-btn">Edit</button>
                  <button onClick={() => handleDelete(user._id)} className="delete-btn">Delete</button>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>

      <style>
        {`
          /* Styles for form and table components */
          .create-user-container { ... }
          .form-container { ... }
          .form-group { ... }
          .submit-btn { ... }
          .user-table { ... }
          .edit-btn { ... }
          .delete-btn { ... }
        `}
      </style>
    </div>
  );
};

export default CreateUser;
